fn resolve_prefix(&self, prefix: &str) -> Result<ChangeId> {
    let p = prefix.to_ascii_lowercase();
    let hex = p.replace('-', "");
    let mut hits: Vec<ChangeId> = self
        .heads()?
        .into_iter()
        .map(|(id, _)| id)
        .filter(|id| id.short().starts_with(&p) || id.to_string().replace('-', "").starts_with(&hex))
        .collect();
    hits.sort();
    hits.dedup();
    match hits.len() {
        1 => Ok(hits[0]),
        0 => Err(Error::NotFound(format!("change {prefix} (svc heads lists the changes; a name from svc branch or an id prefix)"))),
        _ => Err(Error::AmbiguousPrefix {
            prefix: prefix.into(),
            candidates: hits,
        }),
    }
}

